import { test, expect, Page } from '@playwright/test';
import { Selectors } from './selectors';

const APP_URL = process.env.APP_URL ?? 'http://localhost:4000';
const API_URL = process.env.API_URL ?? 'http://localhost:9000';

async function attachConsoleCapture(page: Page) {
  const errors: string[] = [];
  page.on('console', msg => {
    if (msg.type() === 'error') {
      // Ignore React fast refresh expected errors
      if (!msg.text().includes('Fast Refresh')) errors.push(msg.text());
    }
  });
  page.on('pageerror', err => {
    errors.push(err.message);
  });
  return {
    errors,
    assertNoErrors: () => expect(errors).toEqual([]),
  };
}

const XSS_PAYLOADS = [
  '<script>window.__xss=1</script>',
  '<img src=x onerror="window.__xss=1">',
];

const SQLI_PAYLOADS = [
  "' OR '1'='1",
  "'; DROP TABLE users; --",
];

