        const consoleCapture = await attachConsoleCapture(page);
        await page.goto('/');
        await Selectors.home.searchInput(page).fill(payload);
        await Selectors.home.searchButton(page).click();
        const xssTriggered = await page.evaluate(() => (window as any).__xss);
        expect(xssTriggered).toBeUndefined();
